var DF = 0.9, N = 8;
// const { Point, Line, Polygon } = EpiShapeSvg;
var { EpiColors } = EpiColorsPckg;
var epiColors;


function setup() {
	createCanvas(windowWidth, windowHeight);
	// createCanvas(~~(windowHeight*2/3), windowHeight);
	noFill();
	noStroke();
	epiColors = new EpiColors();
	rectMode(CENTER);
	// epiColors.BG = EpiColors.getAdjustedBrightness(EpiColors.getAdjustedSaturation(epiColors.BG, 2), 0.35);
	loop();
}

function draw() {
	epiColors.getRandomPalette(true);
	background(epiColors.getAverageClr()); // "#ffeeff");
	fill(random(epiColors.palette));

	const ctx = drawingContext;
	const x = width/2, y = height/2;
	const d = height / 1.6;

	// draw ring
	for (let i = N; i > 0; i--) {
		shuffle(epiColors.palette, true);
		push();
			const f = i/N;
			const dx = d * f;
			const dy = d * f + d * 0.5;

			if (i == 1) {
				fill(epiColors.getAverageClr()); // last as background

			} else {	
				// get position of clrs between 0..1
				let posArr = [], posSum = 0;
				for (let j = 0; j < epiColors.palette.length; j++) {
					const rndVal = random(0.3, 0.7); // keep min distance to next function posArr.push(rndVal);
					if (j < epiColors.palette.length-1) posSum += rndVal; 
				}
				for (let j = 0; j < epiColors.palette.length; j++) posArr[j] /= posSum; // normalize

				// fill gradient
				const linGrad = ctx.createLinearGradient(x-dx/2, y-dy/2, x-dx/2, y+dy/2);
				for (let j = 0, gradPos = 0; j < epiColors.palette.length; j++) {
					linGrad.addColorStop(
						gradPos, // map(j, 0, epiColors.palette.length-1, 0, 1), 
						epiColors.palette[j]
					);
					// console.log(gradPos);
					gradPos += posArr[j]
				}
				ctx.fillStyle = linGrad;
			}


			rect(x, y, dx, dy, dx/2);
		pop();
	}

	// noLoop() removed for animation
}

function mousePressed() {
	if (mouseButton != RIGHT && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > width*0.1) setup();
}
